<div class="pagination-bar" ng-cloak><span ng-hide="loading">[[pager.total | number]] مورد <span ng-if="pager.total">· نمایش [[pager.from]] تا [[pager.to]]</span></span><div class="pagination-controls"><label for="page-size" class="mb-0">در هر صفحه</label><select id="page-size" class="form-control" ng-model="filters.limit" ng-disabled="loading" ng-change="load(1)" ng-options="size for size in [10,25,50,100]"></select><button class="btn btn-secondary btn-sm" ng-click="load(pager.current_page-1)" ng-disabled="loading || pager.current_page <= 1">قبلی</button><span class="pagination-current" ng-hide="loading">[[pager.current_page]] / [[pager.last_page]]</span><button class="btn btn-secondary btn-sm" ng-click="load(pager.current_page+1)" ng-disabled="loading || pager.current_page >= pager.last_page">بعدی</button></div></div>
